begin;
create extension if not exists pgtap with schema extensions;
select plan(21);
insert into auth.users(id,email) values ('91111111-1111-1111-1111-111111111111','group-a@example.test'),('92222222-2222-2222-2222-222222222222','group-b@example.test');
insert into public.profiles(id,owner_id,display_name) values ('9aaaaaaa-1111-1111-1111-111111111111','91111111-1111-1111-1111-111111111111','A'),('9bbbbbbb-2222-2222-2222-222222222222','92222222-2222-2222-2222-222222222222','B');
select group_private.import_listing('{"id":"90000000-0000-0000-0000-000000000001","name":"Near","area_name":"New York","latitude":40.71,"longitude":-74.01,"description":"Verified fixture","contact_id":"9aaaaaaa-1111-1111-1111-111111111111"}');
select group_private.import_listing('{"id":"90000000-0000-0000-0000-000000000002","name":"Far","area_name":"Elsewhere","latitude":40.90,"longitude":-74.01,"description":"Verified fixture","contact_id":"9bbbbbbb-2222-2222-2222-222222222222","introduction_text":"Approved introduction","introduction_profile_id":"9aaaaaaa-1111-1111-1111-111111111111"}');
select group_private.import_listing('{"id":"90000000-0000-0000-0000-000000000001","name":"Near updated","area_name":"New York","latitude":40.71,"longitude":-74.01,"description":"Updated verified fixture","contact_id":"9aaaaaaa-1111-1111-1111-111111111111"}');
set local role authenticated;
select set_config('request.jwt.claim.sub','91111111-1111-1111-1111-111111111111',true);
select is(jsonb_array_length(public.search_groups(40.71,-74.01,5)->'groups'),1,'radius filters groups');
select is(jsonb_array_length(public.search_groups(40.71,-74.01,30)->'groups'),2,'widening finds other listing');
select is(jsonb_array_length(public.search_groups(0,0,5)->'groups'),0,'no fabricated results');
select is(public.get_group_listing('90000000-0000-0000-0000-000000000001')->'contact'->>'id','9aaaaaaa-1111-1111-1111-111111111111','first contact identity');
select is(public.get_group_listing('90000000-0000-0000-0000-000000000002')->'contact'->>'id','9bbbbbbb-2222-2222-2222-222222222222','second contact identity');
select is(public.get_group_listing('90000000-0000-0000-0000-000000000001')->>'introduction',null,'absent introduction omitted');
select is(public.get_group_listing('90000000-0000-0000-0000-000000000002')->'introduction'->'player'->>'id','9aaaaaaa-1111-1111-1111-111111111111','real introduction identity');
select is(public.get_group_listing('90000000-0000-0000-0000-000000000001')->>'name','Near updated','operator update preserves identity');
select throws_ok($$update public.group_listings set name='Injected'$$,'42501',null,'client listing writes denied');
select throws_ok($$select * from public.group_listings$$,'42501',null,'raw writes and reads private');
select throws_ok($$select group_private.import_listing('{}')$$,'42501',null,'client cannot import');
select is(jsonb_array_length(public.search_groups(40.71,-74.01,30,null,1)->'groups'),1,'bounded page');
select is(public.search_groups(40.71,-74.01,30,public.search_groups(40.71,-74.01,30,null,1)->>'next_cursor',1)->'groups'->0->>'id','90000000-0000-0000-0000-000000000002','cursor reaches next group');
select throws_ok($$select public.search_groups(40.71,-74.01,0)$$,'22023',null,'invalid radius denied');
reset role;
select throws_ok($$select group_private.import_listing('{"id":"90000000-0000-0000-0000-000000000003","contact_id":"90000000-0000-0000-0000-000000000099"}')$$,'22023',null,'nonexistent contact rejected');
set local role anon;
select throws_ok($$select public.get_group_listing('90000000-0000-0000-0000-000000000001')$$,'42501',null,'anonymous detail denied');
select throws_ok($$select public.search_groups(40.71,-74.01,5)$$,'42501',null,'anonymous search denied');
reset role;
update auth.users set banned_until=now()+interval '1 day' where id='92222222-2222-2222-2222-222222222222';
set local role authenticated;
select is(public.get_group_listing('90000000-0000-0000-0000-000000000002')->>'contact',null,'deactivated contact unavailable');
reset role;
delete from public.profiles where id='9aaaaaaa-1111-1111-1111-111111111111';
set local role authenticated;
select is(public.get_group_listing('90000000-0000-0000-0000-000000000001')->>'contact',null,'deleted contact unavailable');
select is(public.get_group_listing('90000000-0000-0000-0000-000000000002')->>'introduction',null,'deleted introduction unavailable');
reset role;
select group_private.remove_listing('90000000-0000-0000-0000-000000000001');
set local role authenticated;
select is(public.get_group_listing('90000000-0000-0000-0000-000000000001'),null,'operator removal takes effect');
select * from finish();
rollback;
